using Captovix;
using System.IO;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
internal static class Program{
 [STAThread]static int Main(string[] args){int count=0;void Check(bool b,string s){if(!b)throw new Exception(s);count++;Console.WriteLine("PASS "+s);}try{
 var pixels=Enumerable.Repeat((byte)255,600*400*4).ToArray();var random=new Random(7);for(int y=0;y<400;y++)for(int x=0;x<600;x++){int n=(y*600+x)*4;pixels[n]=(byte)random.Next(256);pixels[n+1]=(byte)random.Next(256);pixels[n+2]=(byte)random.Next(256);}var source=args.Length==1?MediaStore.LoadImage(args[0]):ImageTransfer.Bitmap(600,400,pixels);int w=source.PixelWidth,h=source.PixelHeight;var baseline=ImageTransfer.Bgra(source);var doc=new EditorDocument{OriginalWidth=w,OriginalHeight=h};var snapshot=EditorRenderer.MockupSnapshot(source,doc,new(0,0,w,h));Check(ImageTransfer.Bgra(snapshot).SequenceEqual(baseline),"Full-quality Mockup scan snapshot is pixel-identical to original opaque source");var candidates=new List<ScanElement>{new(){Bounds=new(10,20,100,30),Kind=MockupKind.Label,Text="Intentionally wrong OCR",Include=true,FontSize=9,FontItalic=true},new(){Bounds=new(0,0,Math.Min(w,500),Math.Min(h,350)),Kind=MockupKind.Block,Include=true}};doc.Annotations.AddRange(MockupRasterState.Attach(ElementScan.Prepare(doc,candidates,new(0,0,w,h)),new(0,0,w,h),Convert.ToBase64String(ImageTransfer.Png(snapshot))));doc.Validate(w,h,"");Check(ImageTransfer.Bgra(EditorRenderer.Render(source,doc)).SequenceEqual(baseline),"Apply all keeps every pixel despite wrong OCR/font/large panel guesses");var saved=EditorDocument.Deserialize(doc.Serialize());saved.Validate(w,h,"");Check(ImageTransfer.Bgra(EditorRenderer.Render(source,saved)).SequenceEqual(baseline),"Save/reopen keeps every source pixel after scan");
 var root=doc.Annotations.Single(a=>a.Mockup!.RasterBacking);var label=doc.Annotations.Single(a=>a.Text.Length>0);var before=doc.Snapshot();label.Text="New";MockupRasterState.Reconcile(before,doc,(a,d)=>throw new Exception("Text edit must not rebuild whole-region recovery"));var modified=ImageTransfer.Bgra(EditorRenderer.Render(source,doc));bool outside=true;for(int y=0;y<h;y++)for(int x=0;x<w;x++)if(x<10||x>=110||y<20||y>=50)for(int c=0;c<4;c++)outside&=modified[(y*w+x)*4+c]==baseline[(y*w+x)*4+c];Check(outside,"Editing one OCR label cannot wipe content outside its own bounds");
 Console.WriteLine($"{count} native release fidelity checks passed. Installer/IME/physical scroll are separate acceptance.");return 0;
 }catch(Exception e){Console.Error.WriteLine(e);return 1;}finally{StaImageWorker.Stop();}}
}
